<script lang="ts">let { label = 'Stop', options = [], onMain = () => {}, onPick = (_v: string) => {} }: { label?: string; options: { value: string; label: string }[]; onMain?: () => void; onPick?: (v: string) => void } = $props();let open = $state(false);</script><div class="split"><button class="main" onclick={onMain}>{label}</button><button class="arrow" aria-label="More options" onclick={() => (open = !open)}>▾</button>{#if open}<div class="menu" role="menu">{#each options as o}<button role="menuitem" onclick={() => { onPick(o.value); open = false; }}>{o.label}</button>{/each}</div>{/if}</div><style>.split{position:relative;display:inline-flex}.main{background:var(--bg-3);border:1px solid var(--border);border-right:none;border-radius:var(--radius) 0 0 var(--radius);color:var(--text-0);padding:var(--space-2) var(--space-4)}.arrow{background:var(--bg-3);border:1px solid var(--border);border-radius:0 var(--radius) var(--radius) 0;color:var(--text-0);padding:var(--space-2)}.menu{position:absolute;top:100%;right:0;background:var(--bg-2);border:1px solid var(--border);border-radius:var(--radius);z-index:20;min-width:140px}.menu button{display:block;width:100%;background:transparent;border:none;color:var(--text-0);padding:var(--space-2) var(--space-4);text-align:left}.menu button:hover{background:var(--bg-3)}</style>
